effect.shader:
const float GM_PI = 3.14159265359;
float gmLuma(vec3 c) { return dot(c, vec3(0.2126, 0.7152, 0.0722)); }
float gmDisc(vec2 p, float r, float soft) { return 1.0 - smoothstep(r, r + soft, length(p)); }
void main() {
vec2 uv = acScreenNorm;
vec2 size = max(inputImg.size, vec2(1.0));
float aspect = size.x / size.y;
vec2 p = (uv - flareCenter) * vec2(aspect, 1.0);
vec2 axis = (vec2(0.5) - flareCenter) * vec2(aspect, 1.0);
vec4 src = texture2DCv(inputImg.texture, uv);
vec3 sourceSample = texture2DCv(inputImg.texture, clamp(flareCenter, 0.0, 1.0)).rgb;
float activation = smoothstep(threshold, min(threshold + 0.25, 1.0), gmLuma(sourceSample));
activation = max(activation, 0.2) * intensity;
float core = gmDisc(p, sourceSize, sourceSize * 1.8);
float r = length(p);
float halo = exp(-pow((r - sourceSize * 4.5) / max(sourceSize * 1.7, 0.001), 2.0));
float angle = atan(p.y, p.x) + rotation;
float blades = max(floor(starPoints + 0.5), 2.0);
float star = pow(abs(cos(angle * blades * 0.5)), 28.0) * exp(-r / max(sourceSize * 7.0, 0.001));
float streak = exp(-abs(p.y) / max(sourceSize * 0.28, 0.0005)) * exp(-abs(p.x) / max(sourceSize * 16.0, 0.001));
vec3 ghosts = vec3(0.0);
for (int i = 0; i < 7; i++) {
float fi = float(i);
float t = -0.35 + fi * 0.28;
vec2 gp = p - axis * t;
float gr = sourceSize * (0.65 + 0.22 * fi);
float ring = exp(-pow((length(gp) - gr) / max(gr * 0.18, 0.0005), 2.0));
vec3 spectral = 0.55 + 0.45 * cos(vec3(0.0, 2.1, 4.2) + fi * 1.37);
ghosts += spectral * ring * (1.0 - fi / 9.0);
}
vec3 flare = flareColor.rgb * (core * 2.2 + halo * haloAmount + star * 1.25 + streak * streakAmount);
flare += ghosts * ghostAmount;
flare *= activation;
vec3 screened = 1.0 - (1.0 - src.rgb) * (1.0 - clamp(flare, 0.0, 1.0));
screened += max(flare - 1.0, 0.0);
gl_FragColor = vec4(mix(src.rgb, screened, mixAmount), src.a);
}
